INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q1', 'GATE', 'CS', '', 2025, '1', 1, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'Ravi had ______ younger brother who taught at ______ university. He was widely regarded as ______ honorable man. Select the option with the correct sequence of articles to fill in the blanks.', ARRAY[ARRAY['a; a; an'], ARRAY['the; an; a'], ARRAY['a; an; a'], ARRAY['an; an; a']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q2', 'GATE', 'CS', '', 2025, '1', 2, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'The CEO''s decision to downsize the workforce was considered myopic because it sacrificed long-term stability to accommodate short-term gains. Select the most appropriate option that can replace the word "myopic" without changing the meaning of the sentence.', ARRAY[ARRAY['visionary'], ARRAY['shortsighted'], ARRAY['progressive'], ARRAY['innovative']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q3', 'GATE', 'CS', '', 2025, '1', 3, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'The average marks obtained by a class in an examination were calculated as 30.8. However, while checking the marks entered, the teacher found that the marks of one student were entered incorrectly as 24 instead of 42. After correcting the marks, the average becomes 31.4. How many students does the class have?', ARRAY[ARRAY['25'], ARRAY['28'], ARRAY['30'], ARRAY['32']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q4', 'GATE', 'CS', '', 2025, '1', 4, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'Consider the relationships among P, Q, R, S, and T: � P is the brother of Q. � S is the daughter of Q. � T is the sister of S. � R is the mother of Q. The following statements are made based on the relationships given above. (1) R is the grandmother of S. (2) P is the uncle of S and T. (3) R has only one son. (4) Q has only one daughter. Which one of the following options is correct?', ARRAY[ARRAY['Both (1) and (2) are true.'], ARRAY['Both (1) and (3) are true.'], ARRAY['Only (3) is true.'], ARRAY['Only (4) is true.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q5', 'GATE', 'CS', '', 2025, '1', 5, 'subj_CS_ga', '', '', 'MCQ', 2, 0, 'According to the map shown in the figure, which one of the following statements is correct? Note: The figure shown is representative. Library 1st Main Road Canteen Physics Lab Hospital 5th Cross Road Chemistry Hostels Classrooms Lab N W E S', ARRAY[ARRAY['The library is located to the northwest of the canteen.'], ARRAY['The hospital is located to the east of the chemistry lab.'], ARRAY['The chemistry lab is to the southeast of physics lab.'], ARRAY['The classrooms and canteen are next to each other.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q6', 'GATE', 'CS', '', 2025, '1', 6, 'subj_CS_cs', '', '', 'MCQ', 2, 0, '"I put the brown paper in my pocket along with the chalks, and possibly other things. I suppose every one must have reflected how primeval and how poetical are the things that one carries in one''s pocket: the pocket-knife, for instance the type of all human tools, the infant of the sword. Once I planned to write a book of poems entirely about the things in my pocket. But I found it would be too long: and the age of the great epics is past." (From G.K. Chesterton''s "A Piece of Chalk") Based only on the information provided in the above passage, which one of the following statements is true?', ARRAY[ARRAY['The author of the passage carries a mirror in his pocket to reflect upon things.'], ARRAY['The author of the passage had decided to write a poem on epics.'], ARRAY['The pocket-knife is described as the infant of the sword.'], ARRAY['Epics are described as too inconvenient to write.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q7', 'GATE', 'CS', '', 2025, '1', 7, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'In the diagram, the lines QR and ST are parallel to each other. The shortest distance between these two lines is half the shortest distance between the point P and line QR. What is the ratio of the area of the triangle PST to the area of the trapezium SQRT? Note: The figure shown is representative. P S T Q R', ARRAY[ARRAY['1'], ARRAY['1'], ARRAY['2'], ARRAY['1']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q8', 'GATE', 'CS', '', 2025, '1', 8, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A fair six-faced dice, with the faces labelled `1'', `2'', `3'', `4'', `5'', and `6'', is rolled thrice. What is the probability of rolling `6'' exactly once?', ARRAY[ARRAY['75'], ARRAY['1'], ARRAY['1'], ARRAY['25']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q9', 'GATE', 'CS', '', 2025, '1', 9, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A square paper, shown in figure (I), is folded along the dotted lines as shown in the figures (II) and (III). Then a few cuts are made as shown in figure (IV). Which one of the following patterns will be obtained when the paper is unfolded? Note: The figures shown are representative. (I) (II) (III) (IV)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q10', 'GATE', 'CS', '', 2025, '1', 10, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A shop has 4 distinct flavors of ice-cream. One can purchase any number of scoops of any flavor. The order in which the scoops are purchased is inconsequential. If one wants to purchase 3 scoops of ice-cream, in how many ways can one make that purchase?', ARRAY[ARRAY['4'], ARRAY['20'], ARRAY['24'], ARRAY['48']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q11', 'GATE', 'CS', '', 2025, '1', 11, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Suppose a program is running on a non-pipelined single processor computer system. The computer is connected to an external device that can interrupt the processor asynchronously. The processor needs to execute the interrupt service routine (ISR) to serve this interrupt. The following steps (not necessarily in order) are taken by the processor when the interrupt arrives: (i) The processor saves the content of the program counter. (ii) The program counter is loaded with the start address of the ISR. (iii) The processor finishes the present instruction. Which ONE of the following is the CORRECT sequence of steps?', ARRAY[ARRAY['(iii), (i), (ii) (B) (i), (iii), (ii)'], ARRAY['(i), (ii), (iii)'], ARRAY['(iii), (ii), (i)']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q12', 'GATE', 'CS', '', 2025, '1', 12, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which ONE of the following statements is FALSE regarding the symbol table?', ARRAY[ARRAY['Symbol table is responsible for keeping track of the scope of variables.'], ARRAY['Symbol table can be implemented using a binary search tree.'], ARRAY['Symbol table is not required after the parsing phase.'], ARRAY['Symbol table is created during the lexical analysis phase.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q13', 'GATE', 'CS', '', 2025, '1', 13, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which ONE of the following techniques used in compiler code optimization uses live variable analysis?', ARRAY[ARRAY['Run-time function call management'], ARRAY['Register assignment to variables'], ARRAY['Strength reduction'], ARRAY['Constant folding']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q14', 'GATE', 'CS', '', 2025, '1', 14, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a demand paging memory management system with 32-bit logical address, 20-bit physical address, and page size of 2048 bytes. Assuming that the memory is byte addressable, what is the maximum number of entries in the page table?', ARRAY[ARRAY['221'], ARRAY['220'], ARRAY['222'], ARRAY['224']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q15', 'GATE', 'CS', '', 2025, '1', 15, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A schedule of three database transactions 1, 2, and 3 is shown. () and () denote read and write of data item by transaction , = 1,2,3. The transaction 1 aborts at the end. Which other transaction(s) will be required to be rolled back? 1() 1() 2() 2() 3() (1)', ARRAY[ARRAY['Only 2'], ARRAY['Only 3'], ARRAY['Both 2 and 3'], ARRAY['Neither 2 nor 3']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q16', 'GATE', 'CS', '', 2025, '1', 16, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Identify the ONE CORRECT matching between the OSI layers and their corresponding functionalities as shown. OSI Layers Functionalities (a) Network layer (I) Packet routing (b) Transport layer (II) Framing and error handling (c) Datalink layer (III) Host to host communication', ARRAY[ARRAY['(a)-(I), (b)-(II), (c)-(III)'], ARRAY['(a)-(I), (b)-(III), (c)-(II)'], ARRAY['(a)-(II), (b)-(I), (c)-(III)'], ARRAY['(a)-(III), (b)-(II), (c)-(I)']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q17', 'GATE', 'CS', '', 2025, '1', 17, 'subj_CS_cs', '', '', 'MCQ', 2, 0, '(. ) is a function from to , (. ) is a function from to , and their composition defined as ((. )) is a mapping from to . If (. ) and ((. )) are onto (surjective) functions, which ONE of the following is TRUE about the function (. )?', ARRAY[ARRAY['(. ) must be an onto (surjective) function.'], ARRAY['(. ) must be a one-to-one (injective) function.'], ARRAY['(. ) must be a bijective function, that is, both one-to-one and onto.'], ARRAY['(. ) is not required to be a one-to-one or onto function.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
