INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q19', 'GATE', 'CS', '', 2025, '1', 19, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following context-free grammar , where , , and are the variables (non-terminals), and are the terminal symbols, is the start variable, and the rules of are described as: | | | Which ONE of the languages () is accepted by ?', ARRAY[ARRAY['() = {2 | 1} {2 | 1}'], ARRAY['() = {2 | 1} {2 | 1}'], ARRAY['() = { | 1}'], ARRAY['() = {22 | 1}']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q20', 'GATE', 'CS', '', 2025, '1', 20, 'subj_CS_cs', '', '', 'MCQ', 2, 0, '() = 2( - 1) + 2 for > 0, (0) = 1. Which ONE of the following options is CORRECT?', ARRAY[ARRAY['() = (22)'], ARRAY['() = (2)'], ARRAY['() = ((log )2 2)'], ARRAY['() = (4)']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q21', 'GATE', 'CS', '', 2025, '1', 21, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following + tree with 5 nodes, in which a node can store at most 3 key values. The value 23 is now inserted in the + tree. Which of the following options(s) is/are CORRECT?', ARRAY[ARRAY['None of the nodes will split.'], ARRAY['At least one node will split and redistribute.'], ARRAY['The total number of nodes will remain same.'], ARRAY['The height of the tree will increase.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q22', 'GATE', 'CS', '', 2025, '1', 22, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the 3-way handshaking protocol for TCP connection establishment. Let the three packets exchanged during the connection establishment be denoted as P1, P2, and P3, in order. Which of the following option(s) is/are TRUE with respect to TCP header flags that are set in the packets?', ARRAY[ARRAY['P3: SYN = 1, ACK = 1'], ARRAY['P2: SYN = 1, ACK = 1'], ARRAY['P2: SYN = 0, ACK = 1'], ARRAY['P1: SYN = 1']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
