INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s1_q47', 'GATE', 'CS', '', 2025, '1', 47, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a relational schema (, , ), with functional dependencies { , }. The relation is decomposed into two relations, 1(, ) and 2(, ). Which of the following statement(s) is/are TRUE?', ARRAY[ARRAY['The relation is NOT in BCNF.'], ARRAY['The relations 1 and 2 are in BCNF.'], ARRAY['The decomposition constitutes a lossless join.'], ARRAY['The relation is NOT in 3NF.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
