INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q41', 'GATE', 'CS', '', 2025, '2', 41, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'An array of length with distinct elements is said to be bitonic if there is an index 1 such that [1. . ] is sorted in the non-decreasing order and [ + 1 . . ] is sorted in the non-increasing order. Which ONE of the following represents the best possible asymptotic bound for the worst-case number of comparisons by an algorithm that searches for an element in a bitonic array ?', ARRAY[ARRAY['()'], ARRAY['(1)'], ARRAY['(log2 )'], ARRAY['(log )']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q42', 'GATE', 'CS', '', 2025, '2', 42, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let be the set of all functions from {1, ... , } to {0,1}. Define the binary relation on as follows: , , if and only if {1, ... , }, () (), where 0 1. Which of the following statement(s) is/are TRUE?', ARRAY[ARRAY['is a symmetric relation'], ARRAY['(, ) is a partial order'], ARRAY['(, ) is a lattice'], ARRAY['is an equivalence relation']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q43', 'GATE', 'CS', '', 2025, '2', 43, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Given the following Karnaugh Map for a Boolean function (, , , ): Which one or more of the following Boolean expression(s) represent(s) ?', ARRAY[ARRAY['+ + + +'], ARRAY['+ + +'], ARRAY['+ + +'], ARRAY['+']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q44', 'GATE', 'CS', '', 2025, '2', 44, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a system of linear equations = where 3�3 and Q 3�1. Suppose has an LU decomposition, = , where 1 00 11 12 13 = [21 1 0] and = [ 0 22 23]. 0 0 33 31 32 1 Which of the following statement(s) is/are TRUE?', ARRAY[ARRAY['The system = can be solved by first solving = and then = .'], ARRAY['If is invertible, then both and are invertible.'], ARRAY['If is singular, then at least one of the diagonal elements of is zero.'], ARRAY['If is symmetric, then both and are symmetric.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q45', 'GATE', 'CS', '', 2025, '2', 45, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a stack data structure into which we can PUSH and POP records. Assume that each record pushed in the stack has a positive integer key and that all keys are distinct. We wish to augment the stack data structure with an (1) time MIN operation that returns a pointer to the record with smallest key present in the stack 1) without deleting the corresponding record, and 2) without increasing the complexities of the standard stack operations. Which one or more of the following approach(es) can achieve it?', ARRAY[ARRAY['Keep with every record in the stack, a pointer to the record with the smallest key'], ARRAY['Keep a pointer to the record with the smallest key in the stack.'], ARRAY['Keep an auxiliary array in which the key values of the records in the stack are'], ARRAY['Keep a Min-Heap in which the key values of the records in the stack are maintained.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q46', 'GATE', 'CS', '', 2025, '2', 46, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following relational schema along with all the functional dependencies that hold on them. R1(A, B, C, D, E): { , , } R2(A, B, C, D): { , , } Which of the following statement(s) is/are TRUE?', ARRAY[ARRAY['R1 is in 3NF'], ARRAY['R2 is in 3NF'], ARRAY['R1 is NOT in 3NF'], ARRAY['R2 is NOT in 3NF']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q47', 'GATE', 'CS', '', 2025, '2', 47, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a demand paging system with three frames, and the following page reference string: 1 2 3 4 5 4 1 6 4 5 1 3 2. The contents of the frames are as follows initially and after each reference (from left to right): initially after - 1* 2* 3* 4* 5* 4 1 6* 4 5 1* 3* 2* - 1 1 1 1 1 11 6 66 6 6 2 - - 2 2 4 4 44 4 44 1 1 1 - - - 3 3 5 55 5 55 5 3 3 The *-marked references cause page replacements. Which one or more of the following could be the page replacement policy/policies in use?', ARRAY[ARRAY['Least Recently Used page replacement policy'], ARRAY['Least Frequently Used page replacement policy'], ARRAY['Most Frequently Used page replacement policy'], ARRAY['Optimal page replacement policy']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q48', 'GATE', 'CS', '', 2025, '2', 48, 'subj_CS_cs', '', '', 'MCQ', 2, 0, '= {1, 2, 3, 4} consists of all active processes in an operating system. = {1, 2, 3, 4} consists of single instances of distinct types of resources in the system. The resource allocation graph has the following assignment and claim edges. Assignment edges: 1 1, 2 2, 3 3, 4 4 (the assignment edge 1 1 means resource 1 is assigned to process 1 , and so on for others) Claim edges: 1 2, 2 3, 3 1, 2 4, 4 2 (the claim edge 1 2 means process 1 is waiting for resource 2 , and so on for others) Which of the following statement(s) is/are CORRECT?', ARRAY[ARRAY['Aborting 1 makes the system deadlock free.'], ARRAY['Aborting 3 makes the system deadlock free.'], ARRAY['Aborting 2 makes the system deadlock free.'], ARRAY['Aborting 1 and 4 makes the system deadlock free.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q49', 'GATE', 'CS', '', 2025, '2', 49, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Three floating point numbers , , and are stored in three registers RX, RY, and RZ, respectively in IEEE 754 single precision format as given below in hexadecimal: RX = 0xC1100000, RY = 0x40C00000, and RZ = 0x41400000 Which of the following option(s) is/are CORRECT?', ARRAY[ARRAY['4( + ) + = 0'], ARRAY['2 � = 0'], ARRAY['4 + 3 = 0'], ARRAY['+ + = 0']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q50', 'GATE', 'CS', '', 2025, '2', 50, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which of the following Boolean algebraic equation(s) is/are CORRECT?', ARRAY[ARRAY['+ + + + = + +'], ARRAY['+ + = +'], ARRAY['( + ) ( + ) = +'], ARRAY['(++)(+)(++)(++) = +']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q51', 'GATE', 'CS', '', 2025, '2', 51, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider two grammars 1 and 2 with the production rules given below: 1: | | 2: | | where , , , , , are the terminals. Which of the following option(s) is/are CORRECT?', ARRAY[ARRAY['1 is not (1) and 2 is (1).'], ARRAY['1 is (1) and 2 is not (1).'], ARRAY['1 and 2 are not (1).'], ARRAY['1 and 2 are ambiguous.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q52', 'GATE', 'CS', '', 2025, '2', 52, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let = {, , }. For , and , let #() denote the number of occurrences of in . Which one or more of the following option(s) define(s) regular language(s)?', ARRAY[ARRAY['{ | , 0}'], ARRAY['{, } {- | 0}'], ARRAY['{ | {, }, #() 2 (mod 7), and #() 3 (mod 9)}'], ARRAY['{ | {, }, #() 2 (mod 7), and #() = #()}']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q53', 'GATE', 'CS', '', 2025, '2', 53, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the database transactions T1 and T2, and data items X and Y. Which of the schedule(s) is/are conflict serializable? Transaction T1 Transaction T2 R1(X) W2(X) W1(Y) W2(Y) R1(X) COMMIT(T2) W1(X) COMMIT(T1)', ARRAY[ARRAY['R1(X), W2(X), W1(Y), W2(Y), R1(X), W1(X), COMMIT(T2), COMMIT(T1)'], ARRAY['W2(X), R1(X), W2(Y), W1(Y), R1(X), COMMIT(T2), W1(X), COMMIT(T1)'], ARRAY['R1(X), W1(Y), W2(X), W2(Y), R1(X), W1(X), COMMIT(T1), COMMIT(T2)'], ARRAY['W2(X), R1(X), W1(Y), W2(Y), R1(X), COMMIT(T2), W1(X), COMMIT(T1)']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q54', 'GATE', 'CS', '', 2025, '2', 54, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following relational schema: Students (rollno: integer, name: string, age: integer, cgpa: real) Courses (courseno: integer, cname: string, credits: integer) Enrolled (rollno: integer, courseno: integer, grade: string) Which of the following options is/are correct SQL query/queries to retrieve the names of the students enrolled in course number (i.e., courseno) 1470?', ARRAY[ARRAY['SELECT S.name'], ARRAY['SELECT S.name'], ARRAY['SELECT S.name'], ARRAY['SELECT S.name']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q55', 'GATE', 'CS', '', 2025, '2', 55, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Given a computing system with two levels of cache (L1 and L2) and a main memory. The first level (L1) cache access time is 1 nanosecond (ns) and the "hit rate" for L1 cache is 90% while the processor is accessing the data from L1 cache. Whereas, for the second level (L2) cache, the "hit rate" is 80% and the "miss penalty" for transferring data from L2 cache to L1 cache is 10 ns. The "miss penalty" for the data to be transferred from main memory to L2 cache is 100 ns. Then the average memory access time in this system in nanoseconds is ___________ . (rounded off to one decimal place) A 5-stage instruction pipeline has stage delays of 180, 250, 150, 170, and 250, respectively, in nanoseconds. The delay of an inter-stage latch is 10 nanoseconds.', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q56', 'GATE', 'CS', '', 2025, '2', 56, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Assume that there are no pipeline stalls due to branches and other hazards. The time taken to process 1000 instructions in microseconds is __________ . (rounded off to two decimal places)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q57', 'GATE', 'CS', '', 2025, '2', 57, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'In a B+- tree where each node can hold at most four key values, a root to leaf path consists of the following nodes: A = (49, 77, 83, -), B = (7, 19, 33, 44), C = (20*, 22*, 25*, 26*) The *-marked keys signify that these are data entries in a leaf. Assume that a pointer between keys 1 and 2 points to a subtree containing keys in [1, 2), and that when a leaf is created, the smallest key in it is copied up into its parent. A record with key value 23 is inserted into the B+- tree. The smallest key value in the parent of the leaf that contains 25* is __________. (Answer in integer) Organising Institute: IIT Roorkee Computer Science and Information Technology (CS2)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q58', 'GATE', 'CS', '', 2025, '2', 58, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'A computer system supports a logical address space of 232 bytes. It uses two-level hierarchical paging with a page size of 4096 bytes. A logical address is divided into a -bit index to the outer page table, an offset within the page of the inner page table, and an offset within the desired page. Each entry of the inner page table uses eight bytes. All the pages in the system have the same size. The value of is ___________ . (Answer in integer)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q59', 'GATE', 'CS', '', 2025, '2', 59, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider the following algorithm someAlgo that takes an undirected graph as input. someAlgo() 1. Let be any vertex in . Run BFS on starting at . Let be a vertex in at maximum distance from as given by the BFS. 2. Run BFS on again with as the starting vertex. Let be the vertex at maximum distance from as given by the BFS. 3. Output the distance between and in . The output of someAlgo() for the tree shown in the given figure is ___________. (Answer in integer) Organising Institute: IIT Roorkee Computer Science and Information Technology (CS2)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q60', 'GATE', 'CS', '', 2025, '2', 60, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Let = {1,2,3,4}. For , let () be the product of symbols in modulo 7. We take () = 1, where is the null string. For example, (124) = (1 � 2 � 4) mod 7 = 1. Define = { | () = 2}. The number of states in a minimum state DFA for is ___________. (Answer in integer)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q61', 'GATE', 'CS', '', 2025, '2', 61, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'An application executes 6.4 � 108 number of instructions in 6.3 seconds. There are four types of instructions, the details of which are given in the table. The duration of a clock cycle in nanoseconds is _________. (rounded off to one decimal place) Instruction type Clock cycles required per Number of instructions instruction (CPI) Branch 2 executed Load 5 2.25 � 108 Store 4 1.20 � 108 Arithmetic 3 1.65 � 108 1.30 � 108 Organising Institute: IIT Roorkee Computer Science and Information Technology (CS2)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q62', 'GATE', 'CS', '', 2025, '2', 62, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider the following C program: #include <stdio.h> int main(){ int a; int arr[5] = {30,50,10}; int *ptr; ptr = &arr[0] + 1; a = *ptr; (*ptr)++; ptr++; printf("%d", a + (*ptr) + arr[1]); return 0; } The output of the above program is ___________. (Answer in integer) Organising Institute: IIT Roorkee Computer Science and Information Technology (CS2)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q63', 'GATE', 'CS', '', 2025, '2', 63, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider the following C program: #include <stdio.h> int g(int n) { return (n+10); } int f(int n) { return g(n*2); } int main() { int sum, n; sum=0; for (n=1; n<3; n++) sum += g(f(n)); printf ("%d", sum); return 0; } The output of the given C program is ________. (Answer in integer)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q64', 'GATE', 'CS', '', 2025, '2', 64, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'A quadratic polynomial ( - )( - ) over complex numbers is said to be square invariant if ( - )( - ) = ( - 2)( - 2). Suppose from the set of all square invariant quadratic polynomials we choose one at random. The probability that the roots of the chosen polynomial are equal is __________. (rounded off to one decimal place) Organising Institute: IIT Roorkee Computer Science and Information Technology (CS2)', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q65', 'GATE', 'CS', '', 2025, '2', 65, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'The unit interval (0,1) is divided at a point chosen uniformly distributed over (0,1) in into two disjoint subintervals. The expected length of the subinterval that contains 0.4 is ___________. (rounded off to two decimal places) Organising Institute: IIT Roorkee', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
