INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q1', 'GATE', 'CS', '', 2024, '1', 1, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'If `'' denotes increasing order of intensity, then the meaning of the words [dry arid parched] is analogous to [diet fast ________ ]. Which one of the given options is appropriate to fill the blank?', ARRAY[ARRAY['starve'], ARRAY['reject'], ARRAY['feast'], ARRAY['deny']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
