INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q13', 'GATE', 'CS', '', 2024, '1', 13, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a system that uses 5 bits for representing signed integers in 2''s complement format. In this system, two integers and are represented as =01010 and =11010. Which one of the following operations will result in either an arithmetic overflow or an arithmetic underflow?', ARRAY[ARRAY['+'], ARRAY['-'], ARRAY['-'], ARRAY['2']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q14', 'GATE', 'CS', '', 2024, '1', 14, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a permutation sampled uniformly at random from the set of all permutations of {1, 2, 3, , } for some 4. Let be the event that 1 occurs before 2 in the permutation, and the event that 3 occurs before 4. Which one of the following statements is TRUE?', ARRAY[ARRAY['The events and are mutually exclusive'], ARRAY['The events and are independent'], ARRAY['Either event or must occur'], ARRAY['Event is more likely than event']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q15', 'GATE', 'CS', '', 2024, '1', 15, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which one of the following statements is FALSE?', ARRAY[ARRAY['In the cycle stealing mode of DMA, one word of data is transferred between an I/O'], ARRAY['For bulk data transfer, the burst mode of DMA has a higher throughput than the'], ARRAY['Programmed I/O mechanism has a better CPU utilization than the interrupt driven'], ARRAY['The CPU can start executing an interrupt service routine faster with vectored']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q16', 'GATE', 'CS', '', 2024, '1', 16, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A user starts browsing a webpage hosted at a remote server. The browser opens a single TCP connection to fetch the entire webpage from the server. The webpage consists of a top-level index page with multiple embedded image objects. Assume that all caches (e.g., DNS cache, browser cache) are all initially empty. The following packets leave the user''s computer in some order. (i) HTTP GET request for the index page (ii) DNS request to resolve the web server''s name to its IP address (iii) HTTP GET request for an image object (iv) TCP SYN to open a connection to the web server Which one of the following is the CORRECT chronological order (earliest in time to latest) of the packets leaving the computer ?', ARRAY[ARRAY['(iv), (ii), (iii), (i)'], ARRAY['(ii), (iv), (iii), (i)'], ARRAY['(ii), (iv), (i), (iii)'], ARRAY['(iv), (ii), (i), (iii)']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q17', 'GATE', 'CS', '', 2024, '1', 17, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Given an integer array of size N, we want to check if the array is sorted (in either ascending or descending order). An algorithm solves this problem by making a single pass through the array and comparing each element of the array only with its adjacent elements. The worst-case time complexity of this algorithm is', ARRAY[ARRAY['both () and () (B) () but not ()'], ARRAY['() but not ()'], ARRAY['neither () nor ()']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q18', 'GATE', 'CS', '', 2024, '1', 18, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following C program: #include <stdio.h> int main(){ int a = 6; int b = 0; while(a < 10) { a = a / 12 + 1; a += b;} printf("%d", a); return 0;} Which one of the following statements is CORRECT?', ARRAY[ARRAY['The program prints 9 as output'], ARRAY['The program prints 10 as output'], ARRAY['The program gets stuck in an infinite loop'], ARRAY['The program prints 6 as output']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q19', 'GATE', 'CS', '', 2024, '1', 19, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following C program: #include <stdio.h> void fX(){ void fX(); char a; int main(){ if((a=getchar()) != ''\\n'') fX(); fX(); if(a != ''\\n'') return 0;} putchar(a);} Assume that the input to the program from the command line is 1234 followed by a newline character. Which one of the following statements is CORRECT?', ARRAY[ARRAY['The program will not terminate'], ARRAY['The program will terminate with no output'], ARRAY['The program will terminate with 4321 as output'], ARRAY['The program will terminate with 1234 as output']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
