INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q36', 'GATE', 'CS', '', 2024, '1', 36, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a network path P--Q--R between nodes P and R via router Q. Node P sends a file of size 106 bytes to R via this path by splitting the file into chunks of 103 bytes each. Node P sends these chunks one after the other without any wait time between the successive chunk transmissions. Assume that the size of extra headers added to these chunks is negligible, and that the chunk size is less than the MTU. Each of the links P--Q and Q--R has a bandwidth of 106 bits/sec, and negligible propagation latency. Router Q immediately transmits every packet it receives from P to R, with negligible processing and queueing delays. Router Q can simultaneously receive on link P--Q and transmit on link Q--R. Assume P starts transmitting the chunks at time = 0. Which one of the following options gives the time (in seconds, rounded off to 3 decimal places) at which R receives all the chunks of the file?', ARRAY[ARRAY['8.000'], ARRAY['8.008'], ARRAY['15.992'], ARRAY['16.000']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
