INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s1_q39', 'GATE', 'CS', '', 2024, '1', 39, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following pseudo-code. 1: 1 = -1 2: 2 = 0 3: 3 = 0 4: 4 = 4 3 5: 5 = 4 2 6: 6 = 5 7: 7 = 4 + 6 8: 8 = [7] 9: if 8 <= goto 11 10: 1 = 8 11: 3 = 3 + 1 12: if 3 < goto 4 13: 2 = 2 + 1 14: if 2 < goto 3 15: = 1 Which one of the following options CORRECTLY specifies the number of basic blocks and the number of instructions in the largest basic block, respectively ?', ARRAY[ARRAY['6 and 6'], ARRAY['6 and 7'], ARRAY['7 and 7'], ARRAY['7 and 6']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
